WITH ship_mode_stats AS (SELECT cs.cs_bill_hdemo_sk AS hd_sk, sm.sm_ship_mode_id, COUNT(*) AS mode_cnt, ROW_NUMBER() OVER (PARTITION BY cs.cs_bill_hdemo_sk ORDER BY COUNT(*) ASC) AS rn FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY cs.cs_bill_hdemo_sk, sm.sm_ship_mode_id), least_ship_mode AS (SELECT hd_sk, sm_ship_mode_id FROM ship_mode_stats WHERE rn = 1), cat_sales AS (SELECT cs.cs_bill_hdemo_sk AS hd_sk, AVG(cs.cs_quantity) AS avg_cat_qty, SUM(cs.cs_net_paid) AS cat_net_paid FROM catalog_sales cs GROUP BY cs.cs_bill_hdemo_sk), store_sales_agg AS (SELECT ss.ss_hdemo_sk AS hd_sk, AVG(ss.ss_quantity) AS avg_store_qty, SUM(ss.ss_net_paid) AS store_net_paid FROM store_sales ss GROUP BY ss.ss_hdemo_sk) SELECT hd.hd_demo_sk, hd.hd_buy_potential, lsm.sm_ship_mode_id AS least_ship_mode, COALESCE(cs.avg_cat_qty, 0) AS avg_cat_quantity, COALESCE(ss.avg_store_qty, 0) AS avg_store_quantity, (COALESCE(cs.avg_cat_qty, 0) + COALESCE(ss.avg_store_qty, 0)) AS total_avg_quantity, (COALESCE(cs.avg_cat_qty, 0) * 100.0) / NULLIF((COALESCE(cs.avg_cat_qty, 0) + COALESCE(ss.avg_store_qty, 0)), 0) AS cat_qty_pct, (COALESCE(ss.avg_store_qty, 0) * 100.0) / NULLIF((COALESCE(cs.avg_cat_qty, 0) + COALESCE(ss.avg_store_qty, 0)), 0) AS store_qty_pct, CASE WHEN (COALESCE(cs.avg_cat_qty, 0) + COALESCE(ss.avg_store_qty, 0)) > 500 THEN 'HIGH_AVG' WHEN (COALESCE(cs.avg_cat_qty, 0) + COALESCE(ss.avg_store_qty, 0)) BETWEEN 200 AND 500 THEN 'MEDIUM_AVG' ELSE 'LOW_AVG' END AS avg_volume_category, DENSE_RANK() OVER (ORDER BY (COALESCE(cs.avg_cat_qty, 0) + COALESCE(ss.avg_store_qty, 0)) DESC) AS avg_quantity_rank FROM household_demographics hd LEFT JOIN cat_sales cs ON hd.hd_demo_sk = cs.hd_sk LEFT JOIN store_sales_agg ss ON hd.hd_demo_sk = ss.hd_sk LEFT JOIN least_ship_mode lsm ON hd.hd_demo_sk = lsm.hd_sk WHERE hd.hd_income_band_sk >= 5 ORDER BY avg_quantity_rank LIMIT 15
